15	import { withAction } from "@/actions/_lib/with-action";
16	import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
17	import { can } from "@/lib/permissions";
18	import {
19	  deleteOrganizationSchema,
20	  type DeleteOrganizationInput,
21	} from "@/schemas/organization";
22	import { deleteOrganization } from "@/server/services/organization-service";
23	import type { ActionResult } from "@/types/api";
24	import type { Organization } from "@/types/organization";
25	import { revalidatePath } from "next/cache";
26	
27	const run = withAction<typeof deleteOrganizationSchema, Organization>(
28	  deleteOrganizationSchema,
29	  async (raw, actor) => {
30	    const input = raw as DeleteOrganizationInput;
31	
32	    if (!can(actor, "org:delete", { kind: "organization", orgId: input.orgId })) {
33	      throw new ForbiddenActionError("org:delete");
34	    }
35	
36	    const organization = await deleteOrganization(actor, input);
37	    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
38	    revalidatePath("/orgs");
